export const reminderLabels={'plan-expiry':'套餐到期提醒','recharge-date':'充值日期提醒','missing-user':'未关联使用人','inactive-user':'使用人已停用','missing-device':'未关联设备','retired-device':'关联设备已停用','missing-account':'未关联运营账号','inactive-accounts':'关联运营账号需核对'};
